WFJ.Data.add("gossip", {
  ["9300b2a7874f5f09"] = { "Finalmente! Naralex può essere risvegliato! Venite ad aiutarmi, valorosi avventurieri!", "." },
  ["9307f78303bb8105"] = { "300? Quindi i Ferroscuro l'hanno ucciso e trascinato nei Sotterranei?", "." },
  ["930ad5a65c6ea72f"] = { "Le ultime notizie dicono che l'⟦Horde=Orda⟧ aveva raccolto $2021w fiorpace su $2020w, $2050w fiordifuoco su $2051w e $2054w fiori di loto purpureo su $2055w.", "." },
  ["930b20ab009eaf50"] = { "Se cerchi la compagnia degli altri paladini, sei nel posto giusto. \r\n\n<Bentornato/Bentornata> a casa.", "." },
  ["9317dea149f76a12"] = { "%s piega un ginocchio a terra.", "." },
  ["932eae0d5bd22c4b"] = { "Con gli abiti che cuce Me'Lynn, verrebbe da pensare che il suo ago sia stato benedetto da Elune in persona. A meno che il tuo ago non sia altrettanto benedetto, ti conviene farle visita e ascoltare i suoi insegnamenti. La trovi alla ⟦Craftsmen's Terrace=Terrazza degli Artigiani⟧, nella parte nord-orientale di Darnassus.", "." },
  ["933471fd27088b53"] = { "Sono Belanaa Windveil, agente dell'High Order qui su Azeroth. Se vuoi donare della stoffa alla nostra organizzazione, te ne saremmo molto grati.", "." },
  ["933c45a1ea760e7e"] = { "<Indegno/Indegna>.", "." },
  ["93416206db46e535"] = { "Silenzio! Non vedi che il padrone sta parlando?", "." },
  ["934a92695649c7eb"] = { "Ehm... papà...? Ci sei? Ho fame... posso avere un po' di stufato?", "." },
  ["93645e22e75f3507"] = { "I grifoni sono pronti a colpire, {name}! Prendi questo segnalatore e piantalo nel cratere occidentale dei campi di battaglia centrali.\n\nFallo e la battaglia sarà nostra!", "." },
  ["936508240730aed1"] = { "Brutta faccenda, quella dei muli... Metz mi farà la pelle per questo fallimento.", "." },
  ["9371a1bdd19b0ab5"] = { "La mia famiglia mi odia. Idioti spaventati, tutti quanti!", "." },
  ["9372a0734b650333"] = { "Cerchi un ladro? Credo che Jannok faccia al caso tuo. Perché non vai a parlargli alla locanda di Dolanaar?", "." },
  ["93736d2db43a181e"] = { "Il Signore di ⟦Blackrock=Roccianera⟧ penzola dagli archi!", "." },
  ["9378095819b6fe6b"] = { "Lavoriamo per preservare l'equilibrio, come insegna Cenarius, {class}. La sua luce è quella di un faro che ci indica la via, e dobbiamo fare tutto ciò che è in nostro potere per preservarla.", "." },
  ["937c9d344d314ee4"] = { "La via del Druido è sorella di quella dello Sciamano. ⟦Gennia Runetotem=Gennia Totem Runico⟧ è immersa in questa sapienza. Cercala nella grande tenda sul lato est del ⟦Bloodhoof Village=Villaggio di Zoccolo Sanguinario⟧.", "." },
  ["937ead45abbc583d"] = { "L'⟦Argent Dawn=Alba d'Argento⟧ non respingerà nessuno che sia disposto a sacrificarsi per la nostra causa.", "." },
  ["9380c2db75b8e730"] = { "Certo che no, <caro/cara> <ragazzo/ragazza>. Voi tipi da «avventurieri» siete spesso vittime delle circostanze, in balia dei drammi politici che tendono a consumarsi tra il popolo e la corona.\n\nIl mio consiglio, quindi, è di cercare qualcos'altro, più precisamente: una nuova carriera.\n\nQuesto mondo ha già abbastanza eroi.", "." },
  ["9382f46620ca3584"] = { "Buon viaggio verso ⟦Ratchet=Porto Paranco⟧, {name}!", "." },
  ["9386378c154ebe7c"] = { "Sfoglia il mio catalogo, {name}.", "." },
  ["93895a9ab052bb65"] = { "Benvenut<o/a> al Pig and Whistle! Prendi da bere, <amico/amica> <mio/mia>, e trova un posto a sedere: più siamo, meglio è!", "." },
  ["9396430b908abc8b"] = { "%s crea un nuovo totem...", "." },
  ["9398c1c7bbaa2deb"] = { "%s freme di energia.", "." },
  ["939c387305030214"] = { "Le ⟦Cliffspring Falls=Cascate di Altafonte⟧ si trovano lungo le montagne, verso est e verso nord.", "." },
  ["939e0746010103d0"] = { "HAI PERSO TU. BUUU.", "." },
  ["939ef6f6346c0fcb"] = { "Be', stai proprio volando! Non posso insegnarti niente che tu non sappia già, ma ⟦Springspindle Fizzlegear=Frizzaruota⟧ di sicuro può! Trovi Springspindle a ⟦Ironforge=Forgiardente⟧. Buona fortuna!", "." },
  ["93b1972baa4f1a62"] = { "Che il Torneo di Pesca ABBIA INIZIO!", "." },
  ["93b38848adf6eae9"] = { "Non sta a noi giudicare queste atrocità. Ivus emetterà il suo giudizio quando arriverà.", "." },
  ["93bd81282ea4a341"] = { "Siamo tornati, e meglio che mai! È la ⟦Darkmoon Faire=Fiera di Lunacupa⟧, <amico/amica>, ed è il tuo giorno fortunato! Senza badare a spese, abbiamo raccolto meraviglie e delizie da tutto il mondo per il tuo divertimento. Giovani o anziani, ricchi o poveri, alla ⟦Darkmoon Faire=Fiera di Lunacupa⟧ c'è tutto per tutti! Non dimenticare di consegnare i tuoi Darkmoon Faire Prize Ticket a ⟦Gelvas Grimegate=Gelvas Strappafizz⟧ e di scegliere fra tanti premi esotici e meravigliosi!", "." },
  ["93bf5b81d26de3fa"] = { "%s si contorce dal dolore mentre il Judgement of Light lo investe!", "." },
  ["93c02db1b95993c3"] = { "{name}, dai un'occhiata al campione di vite Gamboatroce che ho preso nelle caverne, così saprai cosa cercare...", "." },
  ["93c1cf2b310faa8e"] = { "Un'altra mandria radunata con successo!", "." },
  ["93c940320ff65c66"] = { "Tutto il materiale necessario per il contributo dell'Alleanza allo sforzo bellico è stato raccolto, {class}. Aspettiamo che l'Orda completi il suo lavoro, poi passeremo al trasporto del materiale bellico a ⟦Silithus=Silitus⟧.", "." },
  ["93cb9f156ccb23f9"] = { "Krumn è il toro che cerchi. Lo trovi sul livello inferiore, al punto informazioni di ⟦Thunder Bluff=Picco del Tuono⟧.", "." },
  ["93cf84de09c21dd2"] = { "Abbiamo un quarto del silithyst che ci serve! Continuate così!", "." },
  ["93d41747006cd083"] = { "La mia spada Archeus mi ha servito bene in vita, ma ora che il mio spirito può finalmente lasciare questa infelice esistenza, non mi serve più.", "." },
  ["93d45254296c50dd"] = { "Dobbiamo fermare questi furfanti!", "." },
  ["93dd5f91496520e8"] = { "Kar Aman, {name}. Sembri <un/una> {class} forte: faresti bene a comportarti con prudenza in questa zona. Toccare cose di cui non sai nulla, o mancare di rispetto ai tuoi anziani, è giusto motivo di punizione.\n\nPuoi anche non rispettare me o i miei compagni, ma imparerai a rispettare il nostro potere, se commetterai la follia di sfidarci.\n\nOra basta con i convenevoli: c'è qualcosa che posso fare per te?", "." },
  ["93e0957f629bc0b8"] = { "Cittadini dell'⟦Alliance=Alleanza⟧, il Signore di ⟦Blackrock=Roccianera⟧ è caduto! Nefarian è stato sconfitto dalla forza congiunta di {name} e dei suoi alleati!", "." },
  ["93e687b9f83aa0da"] = { "Che cosa cerchi alla mia forgia? L'addestramento? Cerchi forse i segreti dell'acciaio? I misteri della forgia? Parla, recluta!", "." },
  ["93ef6ef10ea54848"] = { "Uuh-uh! Finalmente si esce di qui. Però sarà dura. Tieni gli occhi aperti.", "." },
  ["93efa43339be1e71"] = { "Sono proprio ciò che devi distruggere per liberare il reggimento! Come ti avevo detto, Kirith aveva un piano.\n\nOgnuno dei servitori ha un punto debole. Colpisci la loro forma fisica vicino alle loro pietre finché non sono sul punto di disgregarsi. È in quel momento, e solo in quel momento, che le pietre del vincolo sono vulnerabili. Però devi sbrigarti a distruggere le pietre, perché quando gli schiavi si riprendono tornano di nuovo invulnerabili.", "." },
  ["93f2dbb75e36cd5b"] = { "Come va la sorveglianza dei barili...?", "." },
})
